const calc = (() => {
  const r = rate / 100 / 12, n = years * 12;
  const payment = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  return {r, n, payment, total: payment * n, interest: payment * n - principal};
})()

(() => {
  const f = x => x.toLocaleString("de-CH", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  return htl.html`<div style="padding:12px;border-radius:12px;background:#eef">
  <div>M = P·r / (1 − (1+r)<sup>−n</sup>), r = ${(calc.r*100).toFixed(4)}% per month, n = ${calc.n}</div>
  <div style="font-size:1.6em;font-weight:bold">CHF ${f(calc.payment)} / month</div>
  <div>Total paid CHF ${f(calc.total)} · interest CHF ${f(calc.interest)}</div></div>`;
})()

(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const year = new Date().getFullYear() - 1;
  const by = d3.rollup(rows.filter(r => new Date(r.date).getUTCFullYear() === year), v => d3.sum(v, r => r.revenue), r => new Date(r.date).getUTCMonth());
  const data = d3.range(12).map(m => ({month: new Date(Date.UTC(year, m, 1)), revenue: by.get(m) ?? 0}));
  return Plot.plot({
    width: 800, height: 420, marginLeft: 70, style: {background: "white", fontSize: "14px"},
    title: `Monthly revenue, ${year}`,
    x: {type: "band", tickFormat: d => d3.utcFormat("%b")(d), label: null},
    y: {grid: true, label: "Revenue ($)", tickFormat: "s"},
    marks: [
      Plot.lineY(data, {x: "month", y: "revenue", stroke: "#2563eb", strokeWidth: 2.5}),
      Plot.dot(data, {x: "month", y: "revenue", fill: "#2563eb", r: 5, tip: true}),
      Plot.ruleY([0])
    ]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  svg.selectAll("path").data(arcs).join("path")
    .attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.selectAll("text").data(arcs).join("text")
    .attr("transform", d => `translate(${label.centroid(d)})`)
    .attr("text-anchor", "middle").attr("fill", "white").attr("font-size", 13)
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
}
